S=dict(cls=7,subj="maths",subj_file="maths")
build(dict(S,ch="parallel-and-intersecting-lines",topic="angles-made-by-lines",name_en="Angles made by lines",name_ta="கோடுகள் உருவாக்கும் கோணங்கள்",
 objectives=["Use vertically opposite angles and linear pairs","Find angles made by a transversal on parallel lines"],
 story=("The railway crossing","At a level crossing Sana saw two parallel railway tracks and a straight road cutting across them.\n\"The road makes the same angle with each track,\" said her father. \"That is because the tracks are parallel.\""),
 explain=["When two lines cross, they form four angles. Angles opposite each other are called vertically opposite angles and they are equal. Two angles side by side on a straight line add up to 180° and are called a linear pair.","Lines that never meet, however far they are extended, are parallel. A line that cuts two or more lines is a transversal. When a transversal cuts two parallel lines, corresponding angles are equal, alternate interior angles are equal, and co-interior angles add up to 180°.","These facts help us find unknown angles. If one angle is 70° then its vertically opposite angle is 70° and the angle next to it on the line is 180° − 70° = 110°."],
 terms=["vertically opposite angles","linear pair","transversal","parallel lines","corresponding angles"],
 narr=[("When two lines cross, vertically opposite angles are equal.","vertically opposite angles"),("Two angles forming a straight line add up to 180 degrees. This is a linear pair.","linear pair"),("A transversal cuts parallel lines. Corresponding angles are equal and alternate interior angles are equal.","transversal"),("Co-interior angles on parallel lines add up to 180 degrees.","co-interior angles")],
 ex=("Two lines cross and one angle is 70°. Find the other three angles.",[("The angle opposite 70° is also 70°.","Vertically opposite angles are equal."),("The angle next to 70° on a straight line is 180° − 70° = 110°.","Linear pair adds up to 180°."),("The fourth angle is also 110°. So the angles are 70°, 110°, 70°, 110°.","Opposite angles are equal.")]),
 tb=("A friend says a linear pair always adds up to 90°. How will you correct this?",["A linear pair lies on a straight line, so it adds up to 180°.","90° is for perpendicular lines."],["Mixing 90° and 180°."]),
 summary=["Vertically opposite angles are equal.","A linear pair adds up to 180°.","On parallel lines, corresponding and alternate angles are equal."],
 q=[("mcq",1,"r1-vo","Vertically opposite angles are","equal",[("supplementary always","They are equal."),("always 90°","They are equal but not always 90°.")],"They are opposite each other."),
    ("tf",1,"r1-lp","A linear pair adds up to 180°.",True,"True."),
    ("mcq",2,"r2-70","If one angle is 70°, the angle next to it on a straight line is","110°",[("20°","That is 90° − 70°."),("70°","That is its opposite angle.")],"180° − 70° = 110°."),
    ("tf",2,"r2-par","Parallel lines meet if extended far enough.",False,"False."),
    ("mcq",3,"r3-corr","When a transversal cuts parallel lines, corresponding angles are","equal",[("complementary","They are equal."),("always 180°","They are equal.")],"Same position at each line."),
    ("short",3,"r3-name","What do we call a line that cuts two or more lines?",["transversal","a transversal"],"It is a transversal."),
    ("mcq",4,"r4-cointer","Co-interior angles on parallel lines add up to","180°",[("90°","Not that."),("360°","Not that.")],"They are supplementary."),
    ("tf",4,"r4-alt","Alternate interior angles on parallel lines are equal.",True,"True.")]))
build(dict(S,ch="number-play",topic="patterns-and-puzzles-with-numbers",name_en="Patterns and puzzles with numbers",name_ta="எண் விளையாட்டுகள்",
 objectives=["Use odd, even and divisibility patterns","Solve number puzzles by reasoning"],
 story=("The magic of 9","Aman asked his friend to pick any number, multiply it by 9 and add the digits of the answer. Whatever the friend picked, the digit sum came to 9 or a multiple of 9.\n\"It is not magic,\" said Aman, \"it is a number pattern.\""),
 explain=["Even numbers end in 0, 2, 4, 6 or 8 and odd numbers end in 1, 3, 5, 7 or 9. The sum of two even numbers is even, the sum of two odd numbers is even, and the sum of an odd and an even number is odd.","Divisibility rules help us. A number is divisible by 2 if its last digit is even, by 5 if the last digit is 0 or 5, by 3 if the sum of its digits is divisible by 3, and by 9 if the sum of its digits is divisible by 9. A number is divisible by 10 if it ends in 0.","Puzzles such as number pyramids and sequences use these ideas. In a sequence like 2, 4, 6, 8, ... each term adds 2. In 1, 3, 6, 10, 15, ... the gap grows by one each time."],
 terms=["parity","divisible","sequence","digit sum"],
 narr=[("Even numbers end in 0, 2, 4, 6 or 8. Odd numbers end in 1, 3, 5, 7 or 9.","odd and even"),("Odd plus odd is even. Odd plus even is odd.","sum patterns"),("A number is divisible by 3 if its digit sum is divisible by 3. The same works for 9.","divisibility by 3 and 9"),("Look at the gaps between terms to find the pattern in a sequence.","sequences")],
 ex=("Is 4,521 divisible by 3?",[("Add the digits: 4 + 5 + 2 + 1 = 12.","Digit sum is 12."),("12 is divisible by 3.","So the number passes the test."),("So 4,521 is divisible by 3.","Check: 4521 ÷ 3 = 1507.")]),
 tb=("A friend says the sum of two odd numbers is odd. How will you correct this?",["Try 3 + 5 = 8, which is even.","Two odd numbers always give an even sum."],["Believing a pattern without testing it."]),
 summary=["Odd + odd = even; odd + even = odd.","Digit sums help test divisibility by 3 and 9.","In a sequence, look at the gaps."],
 q=[("mcq",1,"r1-oo","The sum of two odd numbers is","even",[("odd","It is even."),("always 10","Not always 10.")],"3 + 5 = 8."),
    ("tf",1,"r1-last","A number ending in 5 is divisible by 5.",True,"True."),
    ("mcq",2,"r2-div3","Which number is divisible by 3?","4,521",[("4,523","Digit sum 14."),("4,526","Digit sum 17.")],"Digit sum 12."),
    ("tf",2,"r2-nine","If the digit sum is divisible by 9, the number is divisible by 9.",True,"True."),
    ("mcq",3,"r3-seq","The next term in 2, 4, 6, 8 is","10",[("9","Adds 2 each time."),("12","Skips 10.")],"Add 2."),
    ("short",3,"r3-tri","Next in 1, 3, 6, 10, 15 is",["21"],"The gap grows: +6."),
    ("mcq",4,"r4-ten","A number divisible by 10 ends in","0",[("5","That is for 5."),("2","That is for 2.")],"Ends in zero."),
    ("tf",4,"r4-oe","An odd plus an even number is odd.",True,"True.")]))
build(dict(S,ch="a-tale-of-three-intersecting-lines",topic="triangles-angle-sum-and-sides",name_en="Triangles: angle sum and sides",name_ta="முக்கோணங்கள்: கோணங்களின் கூடுதலும் பக்கங்களும்",
 objectives=["State the angle sum property of a triangle","Use the triangle inequality"],
 story=("The straw triangle","Nikhil had three straws of lengths 3 cm, 4 cm and 8 cm and tried to make a triangle. The two shorter straws could not reach each other across the longest straw.\n\"Not every set of three lengths makes a triangle,\" said his teacher."),
 explain=["The three angles of any triangle add up to 180°. So if two angles are 50° and 60°, the third is 180° − 110° = 70°. An exterior angle of a triangle equals the sum of the two opposite interior angles.","Triangles are named by sides: equilateral (all three sides equal, each angle 60°), isosceles (two sides equal, and the angles opposite them are equal) and scalene (no sides equal). By angles they are acute, right or obtuse.","The triangle inequality says that the sum of any two sides of a triangle is greater than the third side. Lengths 3, 4, 8 cannot form a triangle since 3 + 4 = 7 is not more than 8."],
 terms=["angle sum","exterior angle","equilateral","isosceles","triangle inequality"],
 narr=[("The three angles of a triangle add up to 180 degrees.","angle sum 180"),("An equilateral triangle has three equal sides and each angle is 60 degrees.","equilateral"),("An isosceles triangle has two equal sides and two equal angles.","isosceles"),("In a triangle, any two sides together are longer than the third side.","triangle inequality")],
 ex=("Can sides of 5 cm, 7 cm and 10 cm form a triangle?",[("The two shorter sides add up to 5 + 7 = 12.","Check the largest side."),("12 is greater than 10.","The rule holds."),("The other pairs also work, so yes, they form a triangle.","3, 4, 8 would not.")]),
 tb=("A friend says a triangle can have two right angles. How will you show this is wrong?",["Two right angles already add up to 180°.","Then the third angle would be 0°, which is not possible."],["Ignoring the angle sum."]),
 summary=["Angles of a triangle add up to 180°.","Equilateral: all sides equal; isosceles: two equal; scalene: none.","Any two sides add up to more than the third side."],
 q=[("mcq",1,"r1-sum","The angles of a triangle add up to","180°",[("90°","That is a right angle."),("360°","That is a quadrilateral.")],"Always 180°."),
    ("tf",1,"r1-eq","Each angle of an equilateral triangle is 60°.",True,"True."),
    ("mcq",2,"r2-third","Two angles are 50° and 60°. The third is","70°",[("110°","That is their sum."),("80°","Wrong.")],"180° − 110°."),
    ("tf",2,"r2-ext","An exterior angle equals the sum of the two opposite interior angles.",True,"True."),
    ("mcq",3,"r3-ineq","Which sides can form a triangle?","5 cm, 7 cm, 10 cm",[("3 cm, 4 cm, 8 cm","3 + 4 is less than 8."),("2 cm, 2 cm, 6 cm","2 + 2 is less than 6.")],"The sum of two sides must exceed the third."),
    ("short",3,"r3-name","What is a triangle with no equal sides called?",["scalene","scalene triangle"],"Scalene."),
    ("mcq",4,"r4-iso","In an isosceles triangle the angles opposite the equal sides are","equal",[("different","They are equal."),("right angles","Not necessarily.")],"Equal sides mean equal opposite angles."),
    ("tf",4,"r4-two","A triangle can have two right angles.",False,"False.")]))
build(dict(S,ch="working-with-fractions",topic="multiplying-and-dividing-fractions",name_en="Multiplying and dividing fractions",name_ta="பின்னங்களைப் பெருக்குதலும் வகுத்தலும்",
 objectives=["Multiply fractions","Divide by a fraction using the reciprocal"],
 story=("Half of a half","Shreya had half a chocolate bar and gave half of it to her brother. \"How much did I give?\" she asked.\nShe broke the half in two equal parts and saw each part was a quarter of the whole bar.\n\"So half of a half is a quarter,\" she said."),
 explain=["To multiply fractions, multiply the numerators together and multiply the denominators together: 1/2 × 1/2 = 1/4 and 2/3 × 3/5 = 6/15 = 2/5. We then simplify. 'Of' usually means multiply: half of 3/4 is 1/2 × 3/4 = 3/8.","The reciprocal of a fraction is got by turning it upside down. The reciprocal of 3/4 is 4/3 and the product of a fraction and its reciprocal is 1.","To divide by a fraction, multiply by its reciprocal: 3/4 ÷ 2/5 = 3/4 × 5/2 = 15/8. Dividing by a number less than 1 makes the answer bigger, because we are finding how many small parts fit."],
 terms=["numerator","denominator","reciprocal","simplify"],
 narr=[("To multiply fractions, multiply the tops and multiply the bottoms.","multiply fractions"),("Half of a half is a quarter. One half times one half is one quarter.","half of a half"),("The reciprocal of a fraction is the fraction turned upside down.","reciprocal"),("To divide by a fraction, multiply by its reciprocal.","divide by a fraction")],
 ex=("Find 2/3 ÷ 4/9.",[("Divide by a fraction by multiplying by its reciprocal. The reciprocal of 4/9 is 9/4.","Turn the second fraction upside down."),("2/3 × 9/4 = 18/12.","Multiply tops and bottoms."),("Simplify 18/12 to 3/2, which is 1 and 1/2.","Divide top and bottom by 6.")]),
 tb=("A friend says multiplying two fractions always gives a bigger number. How will you show he is wrong?",["1/2 × 1/2 = 1/4, which is smaller than 1/2.","Multiplying by a fraction less than 1 gives a smaller number."],["Assuming multiplication always increases."]),
 summary=["Multiply tops and bottoms, then simplify.","The reciprocal turns the fraction upside down.","Divide by a fraction by multiplying by its reciprocal."],
 q=[("mcq",1,"r1-mul","1/2 × 1/2 =","1/4",[("1","Too big."),("1/2","Not quite.")],"1 × 1 over 2 × 2."),
    ("tf",1,"r1-recip","The reciprocal of 3/4 is 4/3.",True,"True."),
    ("mcq",2,"r2-div","3/4 ÷ 2/5 =","15/8",[("6/20","That multiplies."),("8/15","That inverts the wrong way.")],"3/4 × 5/2."),
    ("tf",2,"r2-big","Multiplying by a fraction less than 1 always makes the number bigger.",False,"False."),
    ("mcq",3,"r3-of","Half of 3/4 is","3/8",[("3/2","Too large."),("1/4","Not right.")],"1/2 × 3/4 = 3/8."),
    ("short",3,"r3-prod","What is 2/3 × 3/5 in simplest form?",["2/5"],"6/15 = 2/5."),
    ("mcq",4,"r4-pr","A fraction times its reciprocal is","1",[("0","Not zero."),("the fraction","It is 1.")],"For example 3/4 × 4/3 = 1."),
    ("tf",4,"r4-simp","We should simplify our final answer.",True,"True.")]))
